arguments.command:
set -euo pipefail
git add -A
printf '%s\n' '--- staged status ---'
git status --short
printf '%s\n' '--- staged summary ---'
git diff --cached --summary
printf '%s\n' '--- staged stat ---'
git diff --cached --stat
printf '%s\n' '--- staged type counts ---'
git diff --cached --name-only | awk '
  /^src\// {src++}
  /^tests\// {tests++}
  /^README\.md$/ {docs++}
  /^\.omo\/ulw-loop\// {ulw++}
  /^\.omo\/evidence\// {evidence++}
  /^\.omo\/senpi-task\// {runtime++}
  END {printf "src=%d tests=%d docs=%d ulw-evidence=%d audit-evidence=%d omo-runtime=%d total=%d\n", src, tests, docs, ulw, evidence, runtime, NR}
'
printf '%s\n' '--- staged integrity ---'
git diff --cached --check
printf '%s\n' '--- staged sensitive-content scan ---'
git diff --cached --no-ext-diff | grep -E '(\+.*(AKIA[0-9A-Z]{16}|-----BEGIN [A-Z ]*PRIVATE KEY-----|gh[pousr]_[A-Za-z0-9_]{20,}|github_pat_[A-Za-z0-9_]{20,}|sk-[A-Za-z0-9]{20,}|xox[baprs]-[A-Za-z0-9-]{20,}|AIza[0-9A-Za-z_-]{20,}))' || true
